update.if:
UPDATE A SET A.EQU_NAME = U.EQU_NAME, A.SIZE = U.SIZE, A.FORM = U.FORM, A.MAKE_BY = U.MAKE_BY, A.DIMENSION = U.DIMENSION, A.INSTALL_DATE = U.INSTALL_DATE, A.INSTALL_PLACE = U.INSTALL_PLACE, A.DISUSE_GBN = U.DISUSE_GBN FROM dbo.TEC_EQUIPMENT A JOIN (
SELECT #{row.LOGIN_OFFICE_CODE} AS OFFICE_CODE, #{row.EQU_GBN} AS EQU_GBN, #{row.EQU_NO} AS EQU_NO, #{row.EQU_NAME} AS EQU_NAME, #{row.SIZE} AS SIZE, #{row.FORM} AS FORM, #{row.MAKE_BY} AS MAKE_BY, #{row.DIMENSION} AS DIMENSION, #{row.INSTALL_DATE} AS INSTALL_DATE, #{row.INSTALL_PLACE} AS INSTALL_PLACE, #{row.DISUSE_GBN} AS DISUSE_GBN
) U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.EQU_GBN = U.EQU_GBN AND A.EQU_NO = U.EQU_NO

mapper.select:
SELECT
	CONVERT(VARCHAR, MAX(CONVERT(INT, A.EQU_NO))) AS EQU_NO
FROM dbo.TEC_EQUIPMENT A
WHERE A.OFFICE_CODE = #{LOGIN_OFFICE_CODE}
  AND A.EQU_GBN = #{EQU_GBN}

update.if:
UPDATE A SET A.DISUSE_GBN = 'Y', A.DISUSE_DATE = U.DISUSE_DATE, A.DISUSE_REASON = U.DISUSE_REASON FROM dbo.TEC_EQUIPMENT A JOIN (
SELECT #{row.LOGIN_OFFICE_CODE} AS OFFICE_CODE, #{row.EQU_GBN} AS EQU_GBN, #{row.EQU_NO} AS EQU_NO, #{row.DISUSE_DATE} AS DISUSE_DATE, #{row.DISUSE_REASON} AS DISUSE_REASON
) U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.EQU_GBN = U.EQU_GBN AND A.EQU_NO = U.EQU_NO

UPDATE A SET A.ST_DATE = U.ST_DATE, A.END_DATE = U.END_DATE, A.TRO_USER = U.TRO_USER, A.TRO_AMT = U.TRO_AMT, A.EQU_USER = U.EQU_USER, A.EQU_HP = U.EQU_HP, A.CONTENT = U.CONTENT, A.REMARKS = U.REMARKS, A.REQ_TIME = U.REQ_TIME, A.ARRIVE_TIME = U.ARRIVE_TIME, A.RESTORE_TIME = U.RESTORE_TIME FROM dbo.TEC_TROUBLE A JOIN (
SELECT #{row.LOGIN_OFFICE_CODE} AS OFFICE_CODE, #{row.EQU_GBN} AS EQU_GBN, #{row.EQU_NO} AS EQU_NO, #{row.REPAIR_SEQ} AS REPAIR_SEQ, #{row.ST_DATE} AS ST_DATE, #{row.END_DATE} AS END_DATE, #{row.TRO_USER} AS TRO_USER, #{row.TRO_AMT} AS TRO_AMT, #{row.EQU_USER} AS EQU_USER, #{row.EQU_HP} AS EQU_HP, #{row.CONTENT} AS CONTENT, #{row.REMARKS} AS REMARKS, #{row.REQ_TIME} AS REQ_TIME, #{row.ARRIVE_TIME} AS ARRIVE_TIME, #{row.RESTORE_TIME} AS RESTORE_TIME
) U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.EQU_GBN = U.EQU_GBN AND A.EQU_NO = U.EQU_NO AND A.REPAIR_SEQ = U.REPAIR_SEQ

mapper.select:
SELECT
	CONVERT(VARCHAR, MAX(CONVERT(INT, A.REPAIR_SEQ))) AS REPAIR_SEQ
FROM dbo.TEC_TROUBLE A
WHERE A.OFFICE_CODE = #{LOGIN_OFFICE_CODE}
  AND A.EQU_GBN     = #{EQU_GBN}
  AND A.EQU_NO      = #{EQU_NO}

mapper.delete:
DELETE FROM dbo.TEC_TROUBLE WHERE EXISTS ( SELECT 1 FROM (
SELECT #{row.LOGIN_OFFICE_CODE} AS OFFICE_CODE, #{row.EQU_GBN} AS EQU_GBN, #{row.EQU_NO} AS EQU_NO, #{row.REPAIR_SEQ} AS REPAIR_SEQ
) AS temp WHERE temp.OFFICE_CODE = TEC_TROUBLE.OFFICE_CODE AND temp.EQU_GBN = TEC_TROUBLE.EQU_GBN AND temp.EQU_NO = TEC_TROUBLE.EQU_NO AND temp.REPAIR_SEQ = TEC_TROUBLE.REPAIR_SEQ )

mapper.select:
SELECT A.OFFICE_CODE AS OFFICE_CODE, A.EQU_GBN AS EQU_GBN, C.MENU_NAME AS EQU_GBN_NM, A.EQU_NO AS EQU_NO, B.EQU_NAME AS EQU_NAME, A.REPAIR_SEQ AS REPAIR_SEQ, A.ST_DATE AS ST_DATE, A.END_DATE AS END_DATE, A.TRO_USER AS TRO_USER, A.TRO_AMT AS TRO_AMT, A.EQU_USER AS EQU_USER, A.EQU_HP AS EQU_HP, A.CONTENT AS CONTENT, A.REMARKS AS REMARKS FROM dbo.TEC_TROUBLE A INNER JOIN dbo.TEC_EQUIPMENT B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EQU_GBN = B.EQU_GBN AND A.EQU_NO = B.EQU_NO LEFT JOIN dbo.TPM_MENU_ADD C ON A.OFFICE_CODE = C.OFFICE_CODE AND A.EQU_GBN = C.MENU_ID WHERE A.OFFICE_CODE = #{LOGIN_OFFICE_CODE} AND A.EQU_GBN = #{EQU_GBN}
AND A.EQU_NO = #{EQU_NO}
AND A.ST_DATE >= #{START_DATE}
AND A.END_DATE <= #{END_DATE}
ORDER BY CONVERT(INT, A.REPAIR_SEQ) DESC, A.ST_DATE

